CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE actors (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES actors(id), title TEXT NOT NULL, purpose TEXT NOT NULL, coordinator_id TEXT REFERENCES actors(id), version INTEGER NOT NULL);
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL REFERENCES actors(id), PRIMARY KEY(workspace_id,actor_id));
CREATE INDEX actor_workspaces ON workspace_members(actor_id,workspace_id);
CREATE TABLE topics (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT NOT NULL, creator_id TEXT NOT NULL REFERENCES actors(id), version INTEGER NOT NULL);
CREATE INDEX workspace_topics ON topics(workspace_id,id);
CREATE TABLE operations (actor_id TEXT NOT NULL REFERENCES actors(id), id TEXT NOT NULL, fingerprint TEXT NOT NULL, kind TEXT NOT NULL, outcome TEXT NOT NULL, PRIMARY KEY(actor_id,id));
CREATE TABLE changes (seq INTEGER PRIMARY KEY AUTOINCREMENT, scope_kind TEXT NOT NULL, scope_id TEXT NOT NULL, resource_kind TEXT NOT NULL, resource_id TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE sqlite_sequence(name,seq);
CREATE INDEX scoped_changes ON changes(scope_kind,scope_id,seq);
CREATE TRIGGER immutable_operations_update BEFORE UPDATE ON operations BEGIN SELECT RAISE(ABORT, 'immutable operation'); END;
CREATE TRIGGER immutable_operations_delete BEFORE DELETE ON operations BEGIN SELECT RAISE(ABORT, 'immutable operation'); END;
CREATE TABLE drafts (id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), source_key TEXT NOT NULL, topic_id TEXT NOT NULL, revision INTEGER NOT NULL, generation TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(actor_id,id), UNIQUE(actor_id,source_key,topic_id));
CREATE TABLE notes (id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), source_key TEXT NOT NULL, revision INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(actor_id,id), UNIQUE(actor_id,source_key));
CREATE TABLE submissions (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), source_key TEXT NOT NULL, topic_id TEXT NOT NULL, prepare_operation_id TEXT NOT NULL, send_operation_id TEXT NOT NULL, send_kind TEXT NOT NULL, authority_id TEXT NOT NULL, authority_epoch TEXT NOT NULL, metadata TEXT NOT NULL, snapshot TEXT NOT NULL, UNIQUE(actor_id,id), UNIQUE(actor_id,send_operation_id));
CREATE INDEX actor_submissions ON submissions(actor_id,seq);
CREATE INDEX editor_submissions ON submissions(actor_id,source_key,topic_id,seq);
CREATE TRIGGER immutable_submissions_update BEFORE UPDATE ON submissions BEGIN SELECT RAISE(ABORT, 'immutable submission'); END;
CREATE TRIGGER immutable_submissions_delete BEFORE DELETE ON submissions BEGIN SELECT RAISE(ABORT, 'immutable submission'); END;
CREATE TABLE delivery_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, recipient_id TEXT NOT NULL REFERENCES actors(id), kind TEXT NOT NULL, topic_id TEXT NOT NULL, participant_epoch INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, pending_count INTEGER NOT NULL DEFAULT 0 CHECK(pending_count>=0), first_pending_seq INTEGER, UNIQUE(recipient_id,kind,topic_id,participant_epoch));
CREATE INDEX eligible_groups ON delivery_groups(recipient_id,id) WHERE active=1 AND pending_count>0;
CREATE INDEX eligible_heads ON delivery_groups(recipient_id,first_pending_seq) WHERE active=1 AND pending_count>0;
CREATE TABLE recipient_schedule (recipient_id TEXT PRIMARY KEY REFERENCES actors(id), enabled INTEGER NOT NULL, pending_count INTEGER NOT NULL DEFAULT 0 CHECK(pending_count>=0), wake_generation INTEGER NOT NULL DEFAULT 0, last_seq INTEGER NOT NULL DEFAULT 0, next_due_ms INTEGER, retry_count INTEGER NOT NULL DEFAULT 0, captured_generation INTEGER, captured_seq INTEGER, claim_token TEXT, claim_until_ms INTEGER);
CREATE INDEX due_recipients ON recipient_schedule(next_due_ms,recipient_id) WHERE enabled=1 AND pending_count>0;
CREATE TRIGGER recipient_enabled AFTER UPDATE OF enabled ON actors BEGIN UPDATE recipient_schedule SET enabled=NEW.enabled WHERE recipient_id=NEW.id; END;
CREATE TABLE topic_participants (topic_id TEXT NOT NULL REFERENCES topics(id), actor_id TEXT NOT NULL REFERENCES actors(id), active INTEGER NOT NULL, epoch INTEGER NOT NULL, responsibility TEXT NOT NULL DEFAULT '', PRIMARY KEY(topic_id,actor_id));
CREATE INDEX participant_topics ON topic_participants(actor_id,active,topic_id);
CREATE TABLE messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, topic_id TEXT NOT NULL REFERENCES topics(id), author_id TEXT NOT NULL REFERENCES actors(id), body TEXT NOT NULL, attachments TEXT NOT NULL, quotes TEXT NOT NULL, addressees TEXT NOT NULL, reply_to TEXT, exchange_id TEXT, operation_id TEXT NOT NULL, UNIQUE(author_id,operation_id));
CREATE INDEX topic_messages ON messages(topic_id,seq);
CREATE INDEX unaddressed_messages ON messages(topic_id,seq) WHERE addressees='[]';
CREATE TABLE message_addressees (topic_id TEXT NOT NULL REFERENCES topics(id), actor_id TEXT NOT NULL REFERENCES actors(id), seq INTEGER NOT NULL REFERENCES messages(seq), PRIMARY KEY(topic_id,actor_id,seq));
CREATE TABLE topic_summaries (topic_id TEXT PRIMARY KEY REFERENCES topics(id), message_count INTEGER NOT NULL, latest_message_id TEXT REFERENCES messages(id));
CREATE TABLE deliveries (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, message_id TEXT NOT NULL REFERENCES messages(id), recipient_id TEXT NOT NULL REFERENCES actors(id), group_id INTEGER NOT NULL REFERENCES delivery_groups(id), state TEXT NOT NULL DEFAULT 'pending', UNIQUE(message_id,recipient_id));
CREATE INDEX recipient_deliveries ON deliveries(recipient_id,state,seq);
CREATE INDEX pending_group_deliveries ON deliveries(group_id,seq) WHERE state='pending';
CREATE TABLE delivery_reasons (delivery_id TEXT NOT NULL REFERENCES deliveries(id), reason TEXT NOT NULL, topic_id TEXT NOT NULL REFERENCES topics(id), participant_epoch INTEGER, PRIMARY KEY(delivery_id,reason));
CREATE TRIGGER immutable_messages_update BEFORE UPDATE ON messages BEGIN SELECT RAISE(ABORT, 'immutable message'); END;
CREATE TRIGGER immutable_messages_delete BEFORE DELETE ON messages BEGIN SELECT RAISE(ABORT, 'immutable message'); END;
CREATE TABLE runner_state (id INTEGER PRIMARY KEY CHECK(id=1), state TEXT NOT NULL, version INTEGER NOT NULL, runner_token TEXT, runner_id TEXT, guard_generation TEXT, lease_until_ms INTEGER, reason_code TEXT, runner_pid INTEGER, runner_started_ms INTEGER, child_pid INTEGER, child_started_at TEXT, child_claim_token TEXT);
CREATE TABLE wake_attempts (id TEXT PRIMARY KEY, claim_token TEXT NOT NULL UNIQUE, runner_token TEXT NOT NULL, recipient_id TEXT NOT NULL REFERENCES actors(id), wake_generation INTEGER NOT NULL, captured_seq INTEGER NOT NULL, started_ms INTEGER NOT NULL, lease_until_ms INTEGER NOT NULL);
CREATE INDEX runner_attempts ON wake_attempts(runner_token,started_ms);
CREATE TABLE wake_results (attempt_id TEXT PRIMARY KEY REFERENCES wake_attempts(id), outcome TEXT NOT NULL, finished_ms INTEGER NOT NULL);
CREATE INDEX active_claim_end ON recipient_schedule(claim_until_ms) WHERE claim_token IS NOT NULL;
CREATE TRIGGER immutable_wake_attempt_update BEFORE UPDATE ON wake_attempts BEGIN SELECT RAISE(ABORT,'immutable wake attempt'); END;
CREATE TRIGGER immutable_wake_attempt_delete BEFORE DELETE ON wake_attempts BEGIN SELECT RAISE(ABORT,'immutable wake attempt'); END;
CREATE TRIGGER immutable_wake_result_update BEFORE UPDATE ON wake_results BEGIN SELECT RAISE(ABORT,'immutable wake result'); END;
CREATE TRIGGER immutable_wake_result_delete BEFORE DELETE ON wake_results BEGIN SELECT RAISE(ABORT,'immutable wake result'); END;
CREATE TABLE memory_items (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, scope_kind TEXT NOT NULL, scope_id TEXT NOT NULL, creator_id TEXT NOT NULL REFERENCES actors(id), current_revision INTEGER NOT NULL);
CREATE INDEX scoped_memory_items ON memory_items(scope_kind,scope_id,seq);
CREATE TABLE memory_revisions (item_id TEXT NOT NULL REFERENCES memory_items(id), revision INTEGER NOT NULL, author_id TEXT NOT NULL REFERENCES actors(id), operation_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, attachments TEXT NOT NULL, refs TEXT NOT NULL, PRIMARY KEY(item_id,revision), UNIQUE(author_id,operation_id));
CREATE TABLE memory_notebooks (scope_kind TEXT NOT NULL, scope_id TEXT NOT NULL, version INTEGER NOT NULL, PRIMARY KEY(scope_kind,scope_id));
CREATE TRIGGER immutable_memory_revision_update BEFORE UPDATE ON memory_revisions BEGIN SELECT RAISE(ABORT, 'immutable Notebook revision'); END;
CREATE TRIGGER immutable_memory_revision_delete BEFORE DELETE ON memory_revisions BEGIN SELECT RAISE(ABORT, 'immutable Notebook revision'); END;
CREATE TRIGGER immutable_memory_identity BEFORE UPDATE ON memory_items WHEN NEW.seq!=OLD.seq OR NEW.id!=OLD.id OR NEW.scope_kind!=OLD.scope_kind OR NEW.scope_id!=OLD.scope_id OR NEW.creator_id!=OLD.creator_id BEGIN SELECT RAISE(ABORT, 'immutable Notebook identity'); END;
CREATE TRIGGER immutable_memory_item_delete BEFORE DELETE ON memory_items BEGIN SELECT RAISE(ABORT, 'immutable Notebook identity'); END;
CREATE TABLE media_intents (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES actors(id), revision INTEGER NOT NULL, state TEXT NOT NULL, publish_operation_id TEXT NOT NULL, authority_id TEXT NOT NULL, authority_epoch TEXT NOT NULL, name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, blob_key TEXT NOT NULL UNIQUE, inline INTEGER NOT NULL DEFAULT 0, UNIQUE(actor_id,publish_operation_id));
CREATE INDEX owned_media ON media_intents(actor_id,id);
CREATE TRIGGER immutable_media_intent BEFORE UPDATE ON media_intents WHEN OLD.state='ready' OR NEW.id!=OLD.id OR NEW.actor_id!=OLD.actor_id OR NEW.publish_operation_id!=OLD.publish_operation_id OR NEW.authority_id!=OLD.authority_id OR NEW.authority_epoch!=OLD.authority_epoch OR NEW.name!=OLD.name OR NEW.content_type!=OLD.content_type OR NEW.size_bytes!=OLD.size_bytes OR NEW.sha256!=OLD.sha256 OR NEW.blob_key!=OLD.blob_key BEGIN SELECT RAISE(ABORT, 'immutable media intent'); END;
CREATE TRIGGER immutable_media_delete BEFORE DELETE ON media_intents BEGIN SELECT RAISE(ABORT, 'immutable media intent'); END;
CREATE TABLE openings (id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), topic_id TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL, state TEXT NOT NULL CHECK (state IN ('open','published','discarded')), payload TEXT NOT NULL, publish_operation_id TEXT, message_id TEXT REFERENCES messages(id), PRIMARY KEY(actor_id,id));
CREATE INDEX open_openings ON openings(actor_id,workspace_id,id) WHERE state='open';
